package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject.GroupKeyVO;

class GroupKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of group key of observed fingerprint rule")
  void test_group_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    GroupKeyValueHolder<Object> value = new GroupKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.groupKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getGroupKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getGroupKey().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.groupKeyNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getGroupKeyValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getGroupKey().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of group key of observed fingerprint rule")
  void test_group_key_value_holder_assign_value_object() {
    Object holder = new Object();
    GroupKeyValueHolder<Object> value = new GroupKeyValueHolder<>(holder);
    GroupKeyVO vo = GroupKeyVO.from("one");
    Assertions.assertFalse(value.getGroupKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.groupKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGroupKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.groupKey(Optional.empty()));
    Assertions.assertFalse(value.getGroupKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.groupKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGroupKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of group key of observed fingerprint rule against the original")
  void test_group_key_value_holder_read() {
    Object holder = new Object();
    GroupKeyValueHolder<Object> value = new GroupKeyValueHolder<>(holder);
    GroupKeyVO vo = GroupKeyVO.from("one");
    GroupKeyVO other = GroupKeyVO.from("one");
    ObservedFingerprintRule original = Mockito.mock(ObservedFingerprintRule.class);
    Mockito.when(original.getGroupKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGroupKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readGroupKey(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.groupKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGroupKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGroupKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of group key of observed fingerprint rule")
  void test_group_key_value_holder_unset() {
    Object holder = new Object();
    GroupKeyValueHolder<Object> value = new GroupKeyValueHolder<>(holder);
    GroupKeyVO vo = GroupKeyVO.from("one");
    value.groupKey(vo);
    Assertions.assertSame(holder, value.unsetGroupKeyIfMatches("groupKey_other"));
    Assertions.assertTrue(value.getGroupKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGroupKeyIfMatches("groupKey"));
    Assertions.assertFalse(value.getGroupKeyValue().isPresent(),
        "The field name must clear the value");
    value.groupKey(vo);
    Assertions.assertSame(holder, value.unsetGroupKey());
    Assertions.assertFalse(value.getGroupKeyValue().isPresent(), "Unset must clear the value");
  }
}
